const pptxgen = require("pptxgenjs");

let pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';
pres.author = 'DiaTool-DPO Research';
pres.title = 'DiaTool-DPO: Enhancing Tool-Augmented LLM Dialogue via Direct Preference Optimization';

// Color palette - Technical/ML theme
const colors = {
  primary: "1E3A5F",      // Dark navy
  secondary: "0D9488",     // Teal
  accent: "14B8A6",        // Light teal
  light: "F1F5F9",         // Light gray
  white: "FFFFFF",
  dark: "0F172A",          // Near black
  text: "1E293B",          // Dark slate
  muted: "64748B",         // Muted gray
  success: "10B981",       // Green
  warning: "F59E0B",        // Amber
  danger: "EF4444"         // Red
};

// Shadow factory to avoid object reuse issues
const makeShadow = () => ({ type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.12 });

// ============ SLIDE 1: Title ============
let slide1 = pres.addSlide();
slide1.background = { color: colors.primary };

// Decorative accent bar at top
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.08, fill: { color: colors.secondary }
});

// Title
slide1.addText("DiaTool-DPO", {
  x: 0.5, y: 1.6, w: 9, h: 0.9,
  fontSize: 48, fontFace: "Arial", bold: true, color: colors.white
});

// Subtitle
slide1.addText("Enhancing Tool-Augmented LLM Dialogue\nvia Direct Preference Optimization", {
  x: 0.5, y: 2.5, w: 9, h: 1.0,
  fontSize: 26, fontFace: "Arial", color: colors.accent
});

// Tagline
slide1.addText("A novel DPO-based method modeling TA-LLM interactions as an MDP with 5 dialogue states and 3 query types", {
  x: 0.5, y: 3.8, w: 7, h: 0.6,
  fontSize: 14, fontFace: "Arial", color: colors.muted
});

// Bottom info bar
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 5.1, w: 10, h: 0.525, fill: { color: colors.dark }
});
slide1.addText("ML Researchers & NLP Engineers  |  Tool-Augmented LLMs & RLHF Alignment", {
  x: 0.5, y: 5.15, w: 9, h: 0.45,
  fontSize: 12, fontFace: "Arial", color: colors.muted, valign: "middle"
});

// ============ SLIDE 2: Problem & Motivation ============
let slide2 = pres.addSlide();
slide2.background = { color: colors.light };

// Header bar
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.9, fill: { color: colors.primary }
});
slide2.addText("SFT Alone Fails to Teach Slot-Filling and Tool Rejection", {
  x: 0.5, y: 0.18, w: 9, h: 0.6,
  fontSize: 26, fontFace: "Arial", bold: true, color: colors.white
});

// Problem statement card
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.1, w: 9, h: 0.8,
  fill: { color: colors.white }, shadow: makeShadow()
});
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.1, w: 0.08, h: 0.8, fill: { color: colors.danger }
});
slide2.addText("TA-LLMs trained only with SFT struggle with incomplete queries and out-of-scope requests, leading to hallucinated tool calls.", {
  x: 0.7, y: 1.2, w: 8.6, h: 0.6,
  fontSize: 14, fontFace: "Arial", color: colors.text, valign: "middle"
});

// Three failure mode cards
const failures = [
  { icon: "1", title: "Missing Follow-Up Questions", desc: "Model fails to ask clarifying questions when required parameters are missing from user queries" },
  { icon: "2", title: "Hallucinated Tool Invocations", desc: "Model makes tool calls with fabricated or incorrect argument values instead of requesting proper slot-filling" },
  { icon: "3", title: "Failed Tool Call Rejection", desc: "Model attempts to use unavailable tools instead of properly rejecting out-of-scope requests" }
];

failures.forEach((f, i) => {
  const x = 0.5 + i * 3.1;

  // Card background
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: x, y: 2.1, w: 2.9, h: 2.6,
    fill: { color: colors.white }, shadow: makeShadow()
  });

  // Number circle
  slide2.addShape(pres.shapes.OVAL, {
    x: x + 1.1, y: 2.25, w: 0.6, h: 0.6,
    fill: { color: colors.danger }
  });
  slide2.addText(f.icon, {
    x: x + 1.1, y: 2.25, w: 0.6, h: 0.6,
    fontSize: 18, fontFace: "Arial", bold: true, color: colors.white, align: "center", valign: "middle"
  });

  // Title
  slide2.addText(f.title, {
    x: x + 0.15, y: 2.95, w: 2.6, h: 0.5,
    fontSize: 13, fontFace: "Arial", bold: true, color: colors.primary, align: "center"
  });

  // Description
  slide2.addText(f.desc, {
    x: x + 0.15, y: 3.45, w: 2.6, h: 1.1,
    fontSize: 11, fontFace: "Arial", color: colors.muted, align: "center"
  });
});

// Solution callout
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 4.85, w: 9, h: 0.55,
  fill: { color: colors.secondary, transparency: 15 }
});
slide2.addText("Solution: Use Direct Preference Optimization to automatically construct paired trajectories of correct vs. incorrect dialogue flows", {
  x: 0.7, y: 4.9, w: 8.6, h: 0.45,
  fontSize: 13, fontFace: "Arial", bold: true, color: colors.primary, valign: "middle"
});

// ============ SLIDE 3: Five-State MDP ============
let slide3 = pres.addSlide();
slide3.background = { color: colors.light };

// Header
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.9, fill: { color: colors.primary }
});
slide3.addText("Modeling TA-LLM Dialogue as a 5-State Markov Decision Process", {
  x: 0.5, y: 0.18, w: 9, h: 0.6,
  fontSize: 24, fontFace: "Arial", bold: true, color: colors.white
});

