  { num: "1", name: "Initial", desc: "No history. Out-of-scope requests return rejection and remain here." },
  { num: "2", name: "Tool Selected\nw/o Complete Slots", desc: "Tool identified but required parameters missing. Slot-filling QA occurs here." },
  { num: "3", name: "Tool Selected\nw/ Complete Slots", desc: "Both tool selection and all argument values are determined." },
  { num: "4", name: "Wait for\nTool Response", desc: "Tool call executed, awaiting results." },
  { num: "5", name: "Complete", desc: "Tool results received, completion message generated for user." }
];

states.forEach((s, i) => {
  const x = 0.4 + i * 1.9;

  // State box
  slide3.addShape(pres.shapes.RECTANGLE, {
    x: x, y: 1.2, w: 1.75, h: 2.4,
    fill: { color: colors.white }, shadow: makeShadow()
  });

  // State number circle
  slide3.addShape(pres.shapes.OVAL, {
    x: x + 0.575, y: 1.35, w: 0.6, h: 0.6,
    fill: { color: colors.secondary }
  });
  slide3.addText(s.num, {
    x: x + 0.575, y: 1.35, w: 0.6, h: 0.6,
    fontSize: 20, fontFace: "Arial", bold: true, color: colors.white, align: "center", valign: "middle"
  });

  // State name
  slide3.addText(s.name, {
    x: x + 0.1, y: 2.05, w: 1.55, h: 0.6,
    fontSize: 11, fontFace: "Arial", bold: true, color: colors.primary, align: "center"
  });

  // Description
  slide3.addText(s.desc, {
    x: x + 0.1, y: 2.65, w: 1.55, h: 0.85,
    fontSize: 9, fontFace: "Arial", color: colors.muted, align: "center"
  });

  // Arrow between states (except last)
  if (i < 4) {
    slide3.addText("→", {
      x: x + 1.7, y: 2.1, w: 0.3, h: 0.5,
      fontSize: 24, fontFace: "Arial", color: colors.secondary, align: "center", valign: "middle"
    });
  }
});

// Key insight box
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 3.85, w: 9, h: 1.5,
  fill: { color: colors.white }, shadow: makeShadow()
});
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 3.85, w: 0.08, h: 1.5, fill: { color: colors.secondary }
});
slide3.addText("Key Insight", {
  x: 0.75, y: 3.95, w: 2, h: 0.4,
  fontSize: 14, fontFace: "Arial", bold: true, color: colors.secondary
});
slide3.addText("The 5 internal states are unobserved — the model must learn to navigate them based on user queries and tool responses. This MDP formulation enables systematic construction of preference pairs for DPO training.", {
  x: 0.75, y: 4.35, w: 8.5, h: 0.9,
  fontSize: 12, fontFace: "Arial", color: colors.text
});

// ============ SLIDE 4: Three Query Types ============
let slide4 = pres.addSlide();
slide4.background = { color: colors.light };

// Header
slide4.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.9, fill: { color: colors.primary }
});
slide4.addText("Three Query Types Define Distinct State Trajectories", {
  x: 0.5, y: 0.18, w: 9, h: 0.6,
  fontSize: 26, fontFace: "Arial", bold: true, color: colors.white
});

// Table header
