const colX = [0.5, 1.7, 4.5, 7.3];

// Header row
slide4.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.1, w: 9, h: 0.5,
  fill: { color: colors.primary }
});
slide4.addText("Query Type", {
  x: colX[0], y: 1.15, w: colWidths[0], h: 0.4,
